// Menu-launched Versus retains the player's ordinary User.ini. Intercept the
// number keys only while a local Versus pawn owns gameplay input.
function bool ApplyVersusSpellKey(EInputKey Key, EInputAction Action)
{
    local HPVersusHarry H;
    if (Action != IST_Press) return False;
    H = GetLocalVersusPawn();
    if (H == None) return False;
    switch (Key)
    {
        case IK_1: H.VersusSpell1(); return True;
        case IK_2: H.VersusSpell2(); return True;
        case IK_3: H.VersusSpell3(); return True;
        case IK_4: H.VersusSpell4(); return True;
        case IK_5: H.VersusSpell5(); return True;
        case IK_6: H.VersusSpell6(); return True;
    }
    return False;
}

function bool ApplyVersusMovementKey(EInputKey Key, EInputAction Action)

ApplyVersusMovementKey(Key, Action);
if (ApplyVersusSpellKey(Key, Action)) return True;
k = Key;
